import React, { createContext, ReactNode, useCallback, useEffect, useMemo, useRef, useState } from 'react';

import type OpenFin from '@openfin/core';

import { ContentMenuEntry } from '@openfin/ui-library';

import { raiseDockAnalytics } from '@common/utils/usage-register';
import { getCurrentOFWindow } from '@common/utils/window';

import { BaseCustomDropdownItem } from '@common/api/action';
import { CompanionDockChannelAction, createChannel, getNamedChannelClient } from '@common/api/protocol/browser';

import { DockCompanionUpdatesPrefix } from '@client-platform/api/dock';
import { MoreMenuCustomOptionPayload } from '@dock3/api/protocol';

import { wrapSync } from '@client-platform/api';
import { Collection, CompanionDockConfig, DockEntry } from '@client-platform/shapes';
import { useUpdateTaskbarIcon } from '@common/hooks/useUpdateTaskbarIcon';
import { useCompanionDockConfiguration } from '@dock3/hooks/useCompanionDockConfiguration';
import { usePlatformIdentity } from '@dock3/hooks/usePlatformIdentity';

const ENTERPRISE_DOCK_CHANNEL_SUFFIX = 'enterprise-dock';

interface DockContextType {
    dockChannel: OpenFin.ChannelProvider;
    dockConfig: CompanionDockConfig;
    favorites: DockEntry[];
    contentMenu: ContentMenuEntry[];
    contentMenuTargetId: string;
    clearContentMenuTargetId: () => void;
    customMenuOptions?: BaseCustomDropdownItem[];
    customMenuLabel?: string;
    moreMenuCustomOptionClicked: (payload: MoreMenuCustomOptionPayload) => Promise<void>;
    collectionMenu: Collection[];
}

/*
 * DockContextProvider is a context provider that manages the state for favorites, content menu entries, and the selected content menu folder.
 * It initializes its state based on the dock window options.
 * Serving as a protocol handler between the dock and the platform, this context enables the dock to synchronize its state with platform updates received via channel messages.
 */
export const DockContext = createContext<DockContextType | undefined>(undefined);

export const DockContextProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [favorites, setFavorites] = useState<DockEntry[]>([]);
    const [contentMenu, setContentMenu] = useState<ContentMenuEntry[]>([]);
    const [collectionMenu, setCollectionMenu] = useState<Collection[]>([]);
    const [contentMenuTargetId, setContentMenuTargetId] = useState<string>();

    const [dockChannel, setDockChannel] = useState<OpenFin.ChannelProvider>();

    // Refs for handling rapid clicks in NavigateContentMenu
    const pendingTargetIdRef = useRef<string | null>(null);
    const navigationFrameRef = useRef<number | null>(null);
    const dockConfig = useCompanionDockConfiguration<CompanionDockConfig>();
    const customMenuConfig = dockConfig?.uiConfig?.moreMenu?.moreMenuCustomOption;
    const customMenuOptions = customMenuConfig?.options || [];
    const customMenuLabel = customMenuConfig?.label;

    const platformIdentity = usePlatformIdentity();

    useUpdateTaskbarIcon(
        dockConfig
            ? {
                  light: typeof dockConfig.icon === 'object' ? dockConfig.icon.light : dockConfig?.icon ?? '',
                  dark: typeof dockConfig.icon === 'object' ? dockConfig.icon.dark : dockConfig?.icon ?? '',
                  custom: true
              }
            : undefined
    );

    const clearContentMenuTargetId = useCallback(() => {
        setContentMenuTargetId(undefined);
    }, []);

    const registerUpdateListeners = useCallback((updateChannel: OpenFin.ChannelProvider) => {
        updateChannel.register(CompanionDockChannelAction.UpdateFavoriteEntries, (favoritesPayload: DockEntry[]) => {
            setFavorites(favoritesPayload);
        });

        updateChannel.register(CompanionDockChannelAction.UpdateContentMenu, (contentMenuPayload: ContentMenuEntry[]) =>
            setContentMenu(contentMenuPayload)
        );

        updateChannel.register(CompanionDockChannelAction.NavigateContentMenu, (targetId: string) => {
            console.log('[DockContext] NavigateContentMenu received:', targetId);
            // Update the pending targetId ref with the latest value
            // This ensures rapid clicks always use the most recent targetId
            pendingTargetIdRef.current = targetId;

            // Clear first to force ContentMenu useEffect to fire, even when clicking same folder again
            setContentMenuTargetId(undefined);

            // If there's already a pending frame, cancel it and create a new one
            // This ensures every click gets processed, even rapid ones
            if (navigationFrameRef.current !== null) {
                cancelAnimationFrame(navigationFrameRef.current);
                navigationFrameRef.current = null;
            }

            // Set the new targetId in the next animation frame
            // Use a double frame to ensure the clear has been processed by React
            navigationFrameRef.current = requestAnimationFrame(() => {
                navigationFrameRef.current = requestAnimationFrame(() => {
                    const finalTargetId = pendingTargetIdRef.current;
                    console.log('[DockContext] Setting contentMenuTargetId:', finalTargetId);
                    if (finalTargetId) {
                        setContentMenuTargetId(finalTargetId);
                    }
                    navigationFrameRef.current = null;
                    pendingTargetIdRef.current = null;
                });
            });
        });

        updateChannel.register(CompanionDockChannelAction.RefreshDockCollectionMenu, (collections: Collection[]) => {
            setCollectionMenu(collections);
        });
    }, []);

    useEffect(() => {
        const windowCloseRequestHandler = () => {
            if (dockConfig?.uiConfig?.moreMenu?.quitPlatform?.skipDialog) {
                fin.Platform.getCurrentSync().quit();
            } else {
                // eslint-disable-next-line no-underscore-dangle
                wrapSync(platformIdentity)._requestQuitPlatformDialog({
                    title: dockConfig?.title,
                    shouldCenterOnMonitor: true
                });
            }
            raiseDockAnalytics(platformIdentity, {
                type: 'More Menu',
                action: 'Quit'
            });
        };

        const win = getCurrentOFWindow();
        win.addListener('close-requested', windowCloseRequestHandler);

        return () => {
            win.removeListener('close-requested', windowCloseRequestHandler);
        };
    }, [platformIdentity, dockConfig]);

    useEffect(() => {
        if (dockConfig?.title) {
            document.title = dockConfig.title;
        }
    }, [dockConfig?.title]);

    useEffect(() => {
        (async () => {
            const windowOptions = await fin.Window.getCurrentSync().getOptions();
            const configFavorites = windowOptions.workspacePlatform.favorites as DockEntry[];
            if (configFavorites) {
                setFavorites(configFavorites);
            }

            const configContentMenu = windowOptions.workspacePlatform.contentMenu as ContentMenuEntry[];
            if (configContentMenu) {
                setContentMenu(configContentMenu);
            }

            if (dockConfig.collectionMenu) {
                setCollectionMenu(dockConfig.collectionMenu);
            }

            if (!dockChannel) {
                const channel = await createChannel(fin.me.identity, DockCompanionUpdatesPrefix);
                registerUpdateListeners(channel);
                setDockChannel(channel);
            }
        })();

        return () => {
            if (dockChannel) {
                dockChannel.destroy();
            }
        };
    }, [registerUpdateListeners, dockConfig]);

    const moreMenuCustomOptionClicked = useCallback(async (payload: MoreMenuCustomOptionPayload): Promise<void> => {
        // Send the action to studio via the enterprise-dock channel
        try {
            const enterpriseChannelClient = await getNamedChannelClient(
                `${fin.me.identity.uuid}-${ENTERPRISE_DOCK_CHANNEL_SUFFIX}`
            );
            await enterpriseChannelClient.dispatch(CompanionDockChannelAction.MoreMenuCustomOptionClicked, payload);
        } catch (error) {
            console.error(
                'DockContext::moreMenuCustomOptionClicked',
                'Failed to send custom menu action to studio:',
                error
            );
        }
    }, []);

    const value = useMemo(
        () => ({
            dockChannel,
            dockConfig,
            favorites,
            contentMenu,
            contentMenuTargetId,
            clearContentMenuTargetId,
            customMenuOptions,
            customMenuLabel,
            moreMenuCustomOptionClicked,
            collectionMenu
        }),
        [
            dockChannel,
            dockConfig,
            favorites,
            contentMenu,
            contentMenuTargetId,
            clearContentMenuTargetId,
            customMenuOptions,
            customMenuLabel,
            moreMenuCustomOptionClicked,
            collectionMenu
        ]
    );

    return <DockContext.Provider value={value}>{children}</DockContext.Provider>;
};
