import React, { useState } from 'react';

import styled from 'styled-components';

import type OpenFin from '@openfin/core';

import { Icon } from '@openfin/ui-library';

import { dock3TestIds } from '@common/utils/test-ids';
import { raiseDockAnalytics } from '@common/utils/usage-register';

import { BaseCustomDropdown } from '@common/components/CustomDropdown/BaseCustomDropdown';

import { wrapSync } from '@client-platform/api';
import { Workspace } from '@client-platform/shapes';

interface Props {
    platformIdentity?: OpenFin.Identity;
    dragging?: boolean;
}

const EnterpriseDockSelector: React.FC<Props> = ({ platformIdentity, dragging }) => {
    const [isLoading, setIsLoading] = useState(false);

    const handleSelect = async (workspace: Workspace) => {
        try {
            setIsLoading(true);
            const platform = wrapSync(platformIdentity);
            raiseDockAnalytics(platformIdentity, {
                type: 'Workspace Selector',
                action: 'Switch Workspace',
                value: workspace.title
            });
            // eslint-disable-next-line no-underscore-dangle
            await platform._handleDockWorkspacesMenuResponseInternal(workspace);
        } finally {
            setIsLoading(false);
        }
    };

    const handleOptions = async () => {
        const platform = wrapSync(platformIdentity);
        // eslint-disable-next-line no-underscore-dangle
        const options = await platform._openDockWorkspacesContextMenuInternal();
        return options;
    };

    return (
        <StyledDropdown
            data-testid={dock3TestIds.enterpriseDockSelectorDropdown}
            tooltip="Saved Workspaces"
            options={handleOptions}
            onSelect={handleSelect}
            disabled={isLoading}
            dragging={dragging}
            showArrow
            rounded
            size="xlarge"
        >
            <Icon icon="StackIcon" size="xlarge" />
        </StyledDropdown>
    );
};

export default EnterpriseDockSelector;

const StyledDropdown = styled(BaseCustomDropdown)`
    height: ${({ theme }) => theme.px.xxxlarge};

    &:hover {
        background-color: var(--color-shared-icon-button-default-background-hover);
    }

    &:active {
        background-color: var(--color-shared-icon-button-default-background-selected);
    }

    &[aria-expanded='true'] {
        background-color: var(--color-shared-icon-button-default-background-pressed);
    }
`;
