import { useEffect, useState } from 'react';

import { ApplicationUUID } from '@common/utils/application';
import { getComponentWindowStatus } from '@common/utils/window';

import { addListenerWithUUID, removeListener } from '@common/api/workspace-events';

export type ComponentsRunning = {
    storefrontRunning: boolean;
    homeRunning: boolean;
};

export const useRunningComponents = (): ComponentsRunning => {
    const [isRunning, setIsRunning] = useState<ComponentsRunning>({ homeRunning: false, storefrontRunning: false });

    useEffect(() => {
        const onComponentStatusUpdate = async () => {
            setIsRunning(await getComponentWindowStatus());
        };
        addListenerWithUUID(ApplicationUUID.Workspace)('component-lifecycle-update', onComponentStatusUpdate);
        onComponentStatusUpdate();
        return () => {
            removeListener('component-lifecycle-update', onComponentStatusUpdate);
        };
    }, []);

    return isRunning;
};
