import type { TaskbarIcon } from '@client-platform/shapes';

type WithIcon = {
    icon?: string | TaskbarIcon;
};

export const getThemedProviderIcon = (provider: WithIcon, isSchemeDark: boolean): string => {
    if (!provider?.icon) {
        return '';
    }

    return typeof provider.icon === 'object'
        ? isSchemeDark
            ? provider.icon.dark
            : provider.icon.light
        : provider?.icon ?? '';
};
