import { useEffect, useState } from 'react';

import type { OpenFin } from '@openfin/core';

type SnapLocation = 'top' | 'bottom';

/**
 * Hook to listen to snap-zone-changed events and track current snap zone locations
 * @returns Array of current snap zone locations (empty if not in any snap zone)
 */
export const useSnapZone = (): SnapLocation[] => {
    const [snapLocations, setSnapLocations] = useState<SnapLocation[]>([]);

    useEffect(() => {
        const currentWindow = fin.Window.getCurrentSync();

        const handleSnapZoneChanged = (event: OpenFin.WindowEvents.SnapZoneChangedEvent) => {
            setSnapLocations(event.locations);
        };

        currentWindow.addListener('snap-zone-changed', handleSnapZoneChanged);

        return () => {
            currentWindow.removeListener('snap-zone-changed', handleSnapZoneChanged);
        };
    }, []);

    return snapLocations;
};
