export const DOCK_COMPANION_HEIGHT = 56;
export const DOCK_COMPANION_WIDTH = 728;
export const DOCK_COMPANION_TOP = 150;

export const DOCK3_WINDOW_NAME = 'dock3';

export const getDock3ChannelName = (uuid?: string): string => {
    const uuidToUse = uuid || (typeof fin !== 'undefined' && fin.me.identity.uuid);
    if (!uuidToUse) {
        throw new Error('UUID is required to get the Dock3 channel name.');
    }
    return `${uuidToUse}-dock3`;
};
