import styled from 'styled-components';

import { ContentMenu, ContentMenuEntry, Text } from '@openfin/ui-library';

import { dock3TestIds } from '@common/utils/test-ids';

import ContentMenuIcon from '@common/assets/icons/companionDock/content-menu-small.svg';

import CloseButtonLarge from '@common/components/CloseButton/CloseButtonLarge';

interface DockContentMenuProps {
    onClose: () => void;
    handleClickItem: (entry: ContentMenuEntry, e: MouseEvent) => void;
    handleFavoriteItem: (entry: ContentMenuEntry) => void;
    contentMenu: ContentMenuEntry[];
    contentMenuTargetId: string;
    disableBookmarking?: boolean;
    selectedScheme?: 'dark' | 'light';
}

const DockContentMenu = ({
    onClose,
    handleClickItem,
    contentMenu,
    contentMenuTargetId,
    disableBookmarking,
    handleFavoriteItem,
    selectedScheme
}: DockContentMenuProps) => {
    return (
        <Container data-testid={dock3TestIds.contentMenuContainer}>
            <ContentMenuHeader data-testid={dock3TestIds.contentMenuHeader}>
                <HeaderLeft>
                    <ContentMenuIcon />
                    <Text as="h2">Content Menu</Text>
                </HeaderLeft>
                <CloseButtonLarge
                    data-testid={dock3TestIds.contentMenuCloseButton}
                    onClick={onClose}
                    aria-label="Close"
                />
            </ContentMenuHeader>
            <ContentMenuWrapper data-testid={dock3TestIds.contentMenuWrapper}>
                <ContentMenu
                    structure={contentMenu}
                    handleBookmarkItem={handleFavoriteItem}
                    handleClickItem={handleClickItem}
                    targetId={contentMenuTargetId}
                    disableBookmarking={disableBookmarking}
                    selectedScheme={selectedScheme}
                />
            </ContentMenuWrapper>
        </Container>
    );
};

const ContentMenuWrapper = styled.div`
    height: 100%;
    min-height: 0;

    & > div[role='tree'] > div {
        border-right: 1px solid var(--color-shared-dock-border-default, var(--color-shared-dock-border));
    }

    .content-menu-item-container-active {
        background-color: var(
            --color-shared-context-menu-item-default-background-active,
            var(--color-role-background-3)
        );
    }

    .content-menu-item-container:hover {
        background-color: var(
            --color-enterprise-context-menu-item-default-background-hover,
            var(--color-role-background-3)
        );
    }
`;

export default DockContentMenu;

const Container = styled.div`
    height: 100%;
    display: flex;
    flex-direction: column;
`;

const ContentMenuHeader = styled.div`
    height: 40px;
    min-height: 40px; // fixes shrinking when new folder contents exceeds viewport height
    width: 100%;
    padding-left: ${({ theme }) => theme.px.base};
    padding-right: ${({ theme }) => theme.px.small};

    display: flex;
    align-items: center;
    justify-content: space-between;

    border-bottom: 1px solid var(--color-shared-dock-border-default, var(--color-shared-dock-border));

    ${Text} {
        user-select: none;
        font-weight: 500;
    }
`;

const HeaderLeft = styled.div`
    display: flex;
    align-items: center;
    gap: ${({ theme }) => theme.px.xsmall};

    svg {
        /* Centers the content menu icon */
        margin-bottom: 1px;

        path {
            fill: var(--color-shared-icon-base);
            stroke: var(--color-shared-icon-base);
        }
    }
`;
