import { useMemo } from 'react';

export const usePlatformIdentity = () => {
    return useMemo(() => {
        if (typeof window !== 'undefined' && typeof fin !== 'undefined') {
            const currentPlatform = fin.Platform.getCurrentSync();
            return {
                ...currentPlatform.identity,
                name: currentPlatform.identity.uuid
            };
        }
        return null;
    }, []);
};
