import OpenFin from '@openfin/core';

import { getBrowserBaseUrl } from '@common/utils/browser-base-url';
import { DefaultSaveMenuBounds } from '@common/utils/context-menu';
import { showChildWindow } from '@common/utils/menu-window-provider';
import { getResponseModalBoundsAndCenterParentIfModalOffScreen } from '@common/utils/modal-bounds';
import { PositioningType } from '@common/utils/positioning';
import Route from '@common/utils/route';
import { raiseDockAnalytics } from '@common/utils/usage-register';
import { getMonitorWindowMostOn, WindowName } from '@common/utils/window';

import { DOCK_COMPANION_WIDTH } from '@dock3/api/constants';

import { DockCompanionButton, OpenSaveWorkspaceMenuRequest } from '@client-platform/shapes';

export const raiseDockButtonAnalytics = (platformIdentity: OpenFin.Identity, buttonLabel?: DockCompanionButton) =>
    raiseDockAnalytics(platformIdentity, {
        type: 'Workspace Section',
        action: 'Select Dock Item',
        value: buttonLabel
    });

export const resizeDockWindow = async (dockWindow: OpenFin.Window, height: number, anchorBottom?: boolean) => {
    const dockWindowBounds = await dockWindow.getBounds();
    if (anchorBottom) {
        await dockWindow.setBounds({
            height,
            width: DOCK_COMPANION_WIDTH,
            top: dockWindowBounds.bottom - height
        });
    } else {
        await dockWindow.setBounds({ height, width: DOCK_COMPANION_WIDTH });
    }
};

export const getShouldAnchorDockAtBottom = async (dockWindow: OpenFin.Window, height: number) => {
    const dockWindowBounds = await dockWindow.getBounds();
    const monitorBounds = (await getMonitorWindowMostOn(dockWindowBounds)).availableRect;
    return dockWindowBounds.top + height > monitorBounds.bottom;
};

type MenuSearchParams = {
    menuType: string;
    invocationId: string;
    id?: string;
    positioning?: string;
};

export const openSaveWorkspaceModal = async ({ menuType, id }: OpenSaveWorkspaceMenuRequest) => {
    const menuOptions: MenuSearchParams = {
        menuType,
        invocationId: Date.now().toString(),
        positioning: PositioningType.RelativeToMonitor
    };
    id && (menuOptions.id = id);

    const windowOpts = {
        url: (await getBrowserBaseUrl()) + Route.BrowserPopupMenuSaveModal,
        // This is the name of the dialog window that will be opened for saving workspaces
        // We set it to a specific name to avoid it being closed when indicator window closes because of the logic in (browserModalCleanup):
        // https://github.com/openfin/workspace/blob/584e72e55ddc155a09e74d97a803d1e45c7e13bd/client-api-platform/src/init/cleanup.ts#L8
        name: WindowName.DockSaveWorkspaceMenu,
        defaultWidth: DefaultSaveMenuBounds.width,
        defaultHeight: DefaultSaveMenuBounds.height
    };

    const bounds = await getResponseModalBoundsAndCenterParentIfModalOffScreen(windowOpts);

    const popupWin = await showChildWindow({
        options: {
            url: windowOpts.url,
            name: windowOpts.name,
            defaultHeight: windowOpts.defaultHeight,
            defaultWidth: windowOpts.defaultWidth,
            defaultLeft: bounds.left,
            defaultTop: bounds.top,
            left: bounds.left,
            top: bounds.top
        },
        parameters: new URLSearchParams(menuOptions)
    });

    return popupWin.identity;
};
