import { useEffect, useState } from 'react';

import type OpenFin from '@openfin/core';

const LOCAL_STORAGE_KEY = 'alwaysOnTop';

export const useAlwaysOnTopSetting = () => {
    const [alwaysOnTop, setAlwaysOnTop] = useState<boolean>(() => {
        if (typeof window !== 'undefined') {
            const storedValue = window.localStorage.getItem(LOCAL_STORAGE_KEY);
            return storedValue !== null ? JSON.parse(storedValue) : true;
        }
        return true;
    });

    useEffect(() => {
        const errorHandler = (e: any) => console.error('Error updating alwaysOnTop', e);
        const window = fin.me as OpenFin.Window;
        if (window) {
            window.getOptions().then((options) => {
                if (options.alwaysOnTop !== alwaysOnTop) {
                    window.updateOptions({ alwaysOnTop }).catch(errorHandler);
                }
            });
        }
    }, [alwaysOnTop]);

    useEffect(() => window.localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(alwaysOnTop)), [alwaysOnTop]);

    return [alwaysOnTop, setAlwaysOnTop] as const;
};
