import { useMemo } from 'react';

import OpenFin from '@openfin/core';

import { raiseDockAnalytics } from '@common/utils/usage-register';
import { getCurrentOFWindow } from '@common/utils/window';

import { wrapSync } from '@client-platform/api';
import { CompanionDockConfig, Dock3Config } from '@client-platform/shapes';

export const useActionsHandler = (
    companionDockConfig: Dock3Config | CompanionDockConfig,
    platformIdentity: OpenFin.Identity,
    alwaysOnTop: boolean,
    setAlwaysOnTop: (v: boolean) => void
): { [key: string]: () => void } => {
    return useMemo(
        () => ({
            minimize: () => {
                getCurrentOFWindow()
                    .minimize()
                    .catch((err) => {
                        console.error(`failed to minimize: ${err}`);
                    });
                raiseDockAnalytics(platformIdentity, {
                    type: 'More Menu',
                    action: 'Minimize'
                });
            },
            quit: () => {
                if (companionDockConfig.uiConfig?.moreMenu?.quitPlatform?.skipDialog) {
                    fin.Platform.getCurrentSync().quit();
                } else {
                    // eslint-disable-next-line no-underscore-dangle
                    wrapSync(platformIdentity)._requestQuitPlatformDialog({
                        title: companionDockConfig.title,
                        shouldCenterOnMonitor: true
                    });
                }

                raiseDockAnalytics(platformIdentity, {
                    type: 'More Menu',
                    action: 'Quit'
                });
            },
            alwaysOnTop: () => {
                setAlwaysOnTop(!alwaysOnTop);
                raiseDockAnalytics(platformIdentity, {
                    type: 'More Menu',
                    action: 'Always On Top'
                });
            }
        }),
        [companionDockConfig, alwaysOnTop, setAlwaysOnTop]
    );
};
