import { useEffect, useState } from 'react';

import type { OpenFin } from '@openfin/core';

export type Options = OpenFin.WindowOptions | OpenFin.ViewOptions;

export function useInitialOptions<T extends Options>() {
    const [initial, setInitial] = useState<T | null>(() => {
        if (typeof fin !== 'undefined') {
            // @ts-expect-error undocumented property
            return fin?.__internal_?.initialOptions ?? null;
        }
        return null;
    });

    useEffect(() => {
        if (!initial) {
            fin.me
                .getOptions?.()
                .then((opts) => setInitial(opts as T))
                .catch(() => {
                    console.error('Failed to fetch initial options');
                });
        }
        // Only want to run this hook once on startup
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    return initial;
}
