import type { ContentMenuEntry } from '@openfin/ui-library';

import makeGetChannelClient from '@common/utils/channels';
import { isLandingPage } from '@common/utils/enterpriseBrowser';
import { getLandingPageUrls, makeNewLandingPage } from '@common/utils/landing-page';
import { mapContentComponentState } from '@common/utils/layout';
import { menuEvents } from '@common/utils/menu-window-provider';
import { WindowName } from '@common/utils/window';

import { BrowserChannelAction, CompanionDockChannelAction, getChannelClient } from '@common/api/protocol/browser';

import { selectAppropriateWindow } from '@client-platform/init/browser-window-focus';
import {
    Collection,
    DockCompanionButton,
    DockEntry,
    EnterpriseDockChannelClient,
    LaunchDockEntryPayload
} from '@client-platform/shapes';

import { getCurrentSync } from '.';

export const DockCompanionUpdatesPrefix = 'dock-companion-updates';

const getDockWindow = async () =>
    (await fin.Application.getCurrentSync().getChildWindows()).find((e) => {
        return e.identity.name === WindowName.DockCompanion;
    });

export const refreshDockBookmarksPanel = async () => {
    const dockWindow = await getDockWindow();
    if (dockWindow) {
        const channelClient = await getChannelClient(dockWindow.identity, DockCompanionUpdatesPrefix);
        await channelClient.dispatch(BrowserChannelAction.RefreshBookmarksInternal);
    }
};

export const updateDockFavoriteEntries = async (favorites: DockEntry[]) => {
    const dockWindow = await getDockWindow();
    if (dockWindow) {
        const channelClient = await getChannelClient(dockWindow.identity, DockCompanionUpdatesPrefix);
        await channelClient.dispatch(CompanionDockChannelAction.UpdateFavoriteEntries, favorites);
    } else {
        throw new Error('Companion Dock window not found');
    }
};

export const updateContentMenu = async (contentMenu: ContentMenuEntry[]) => {
    const dockWindow = await getDockWindow();
    if (dockWindow) {
        const channelClient = await getChannelClient(dockWindow.identity, DockCompanionUpdatesPrefix);
        await channelClient.dispatch(CompanionDockChannelAction.UpdateContentMenu, contentMenu);
    } else {
        throw new Error('Companion Dock window not found');
    }
};

export const navigateContentMenu = async (id: string) => {
    const dockWindow = await getDockWindow();
    if (dockWindow) {
        const channelClient = await getChannelClient(dockWindow.identity, DockCompanionUpdatesPrefix);
        await channelClient.dispatch(CompanionDockChannelAction.NavigateContentMenu, id);
    } else {
        throw new Error('Companion Dock window not found');
    }
};

const enterpriseDockChannelClient = makeGetChannelClient(
    `${typeof fin !== 'undefined' && fin?.me.identity.uuid}-enterprise-dock`
) as () => Promise<EnterpriseDockChannelClient>;

export const refreshDockCollectionMenu = async (collections: Collection[]) => {
    const dockWindow = await getDockWindow();
    if (dockWindow) {
        const channelClient = await getChannelClient(dockWindow.identity, DockCompanionUpdatesPrefix);
        await channelClient.dispatch(CompanionDockChannelAction.RefreshDockCollectionMenu, collections);
    }
    // Always update enterprise dock channel regardless
    const channel = await enterpriseDockChannelClient();
    return channel.dispatch('refresh-dock-collection-menu', collections);
};

export const launchDockEntry = async (payload: LaunchDockEntryPayload) => {
    const channel = await enterpriseDockChannelClient();
    return channel.dispatch('launch-entry', payload);
};

