import { useCallback, useContext } from 'react';

import { ContentMenuEntry } from '@openfin/ui-library';

import DockContentMenu from '@dock3/components/DockContentMenu';

import { getCurrentSync } from '@client-platform/api';
import { DockEntry } from '@client-platform/index';
import { DockContext } from '@enterprise/context/DockContext';

interface DockContentMenuProps {
    onClose: () => void;
}

const deleteChildren = (entry: ContentMenuEntry) => {
    if (entry.type === 'folder') {
        const { children: _children, ...noChildrenEntry } = entry;
        return noChildrenEntry;
    }
    return entry;
};

export const EnterpriseDockContentMenu = ({ onClose }: DockContentMenuProps) => {
    const { contentMenu, contentMenuTargetId } = useContext(DockContext);

    const handleClickItem = useCallback((entry: ContentMenuEntry, e: MouseEvent) => {
        // eslint-disable-next-line no-underscore-dangle
        getCurrentSync()._launchDockEntryInternal({
            entry: deleteChildren(entry) as DockEntry,
            sourceEvent: {
                ctrlKey: e.ctrlKey,
                metaKey: e.metaKey,
                shiftKey: e.shiftKey
            }
        });
    }, []);

    const handleFavoriteItem = useCallback((entry: ContentMenuEntry) => {
        if (entry.bookmarked) {
            // eslint-disable-next-line no-underscore-dangle
            getCurrentSync()._removeDockFavoriteInternal(entry as DockEntry);
        } else {
            // eslint-disable-next-line no-underscore-dangle
            getCurrentSync()._addDockFavoriteInternal(deleteChildren(entry) as DockEntry);
        }
    }, []);

    return (
        <DockContentMenu
            onClose={onClose}
            handleClickItem={handleClickItem}
            handleFavoriteItem={handleFavoriteItem}
            contentMenu={contentMenu}
            contentMenuTargetId={contentMenuTargetId}
        />
    );
};
