import { useRef, useState } from 'react';

import type OpenFin from '@openfin/core';

import {
    EmptyContextMenuItem,
    MenuItemType,
    showContextMenu,
    ShowContextMenuResponse
} from '@common/utils/context-menu';
import { urlToBase64 } from '@common/utils/image-url-to-base64';

import { BaseCustomDropdownItem, BaseCustomDropdownItems } from '@common/api/action';

const DEBOUNCE_TIME = 150;

export const useDropdown = () => {
    const [isDropdownShowing, setIsDropdownShowing] = useState(false);
    const isDropdownShowingTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

    const onShowDropdown = (options: BaseCustomDropdownItems, onSelect: (data: any) => void) => {
        return async (event: any) => {
            /* eslint-disable-next-line no-unsafe-optional-chaining */
            const { bottom, left } = event.currentTarget?.getBoundingClientRect();

            setIsDropdownShowing(true);

            const opts = typeof options === 'function' ? await options() : options;

            const convertItemToCtxMenuOption = async (
                item: BaseCustomDropdownItem
            ): Promise<OpenFin.MenuItemTemplate> => {
                const baseProperties = {
                    icon: item.iconUrl ? await urlToBase64(item.iconUrl, 20, 20) : '',
                    label: item.tooltip,
                    enabled: !item.disabled
                };
                if (item.separator) {
                    return { type: MenuItemType.Separator };
                }
                if (item.options) {
                    return {
                        ...baseProperties,
                        submenu: await Promise.all(item.options.map(convertItemToCtxMenuOption))
                    };
                } else {
                    return {
                        ...baseProperties,
                        type: typeof item.checked === 'boolean' ? MenuItemType.Checkbox : MenuItemType.Label,
                        data: item.action,
                        checked: item.checked === true
                    };
                }
            };

            const ctxMenuOptions = opts.map(convertItemToCtxMenuOption);

            const handleResult = (res: ShowContextMenuResponse) => {
                if (isDropdownShowingTimeout.current) {
                    clearTimeout(isDropdownShowingTimeout.current);
                }
                isDropdownShowingTimeout.current = setTimeout(() => {
                    setIsDropdownShowing(false);
                    isDropdownShowingTimeout.current = null;
                }, DEBOUNCE_TIME);

                if (res.result !== 'closed') {
                    onSelect(res.data);
                }
            };

            const template = await Promise.all(ctxMenuOptions);

            showContextMenu({
                template: template.length ? template : [EmptyContextMenuItem],
                x: left,
                y: bottom + 4
            }).then(handleResult);
        };
    };

    return { isDropdownShowing, onShowDropdown };
};
