import { useEffect, useMemo, useState } from 'react';

import { getCurrentSync } from '@client-platform/api';
import { CompanionDockConfig, Dock3Button, Dock3Config, DockCompanionButton } from '@client-platform/shapes';
import useIsNotificationsRunning from '@common/hooks/useIsNotificationsRunning';
import { useRunningComponents } from '@common/hooks/useRunningComponents';

export const useDefaultDockButtonsDynamic = (
    dockConfig: Dock3Config | CompanionDockConfig
): [
    (DockCompanionButton | Dock3Button)[],
    // Updater is only used in enterprise
    (updatedDefaultDockButtons: (DockCompanionButton | Dock3Button)[]) => void
] => {
    const [defaultDockButtons, setDefaultDockButtons] = useState<(DockCompanionButton | Dock3Button)[]>([]);
    const isNotificationsRunning = useIsNotificationsRunning();
    const { homeRunning, storefrontRunning } = useRunningComponents();

    useEffect(() => {
        setDefaultDockButtons(dockConfig?.defaultDockButtons || []);
    }, [dockConfig]);

    const dynamicallyConfigured = useMemo(
        () =>
            defaultDockButtons.filter((button) => {
                if (button === 'home' && !homeRunning) {
                    return false;
                }

                if (button === 'notifications' && !isNotificationsRunning) {
                    return false;
                }

                if (button === 'store' && !storefrontRunning) {
                    return false;
                }

                return true;
            }),
        [defaultDockButtons, homeRunning, isNotificationsRunning, storefrontRunning]
    );

    return [
        dynamicallyConfigured,
        (updatedDefaultDockButtons: DockCompanionButton[]) => {
            setDefaultDockButtons(
                updatedDefaultDockButtons.concat(
                    (defaultDockButtons as DockCompanionButton[]).filter((b) => !updatedDefaultDockButtons.includes(b))
                )
            );
            // eslint-disable-next-line no-underscore-dangle
            getCurrentSync()._setDefaultDockButtonsOrderInternal(updatedDefaultDockButtons);
        }
    ];
};
