import React, { useState } from 'react';

import styled from 'styled-components';

import { motion } from 'framer-motion';
import debounce from 'lodash.debounce';

import { Icon } from '@openfin/ui-library';

import { dock3TestIds } from '@common/utils/test-ids';
import { raiseDockAnalytics } from '@common/utils/usage-register';
import { homeOFIdentity, isWindowRunning, showAndFocus, storefrontOFIdentity } from '@common/utils/window';

import ContentMenuIcon from '@common/assets/icons/companionDock/content-menu.svg';
import DockBookmark from '@common/assets/icons/companionDock/dock-bookmark.svg';

import NotificationsButton from '@common/components/NotificationsButton/NotificationsButton';

import CollectionMenu from '@dock3/components/CollectionMenu';
import ManageWorkspaces from '@dock3/components/ManageWorkspaces';
import PlatformDockSelector from '@dock3/components/PlatformDockSelector';

import { getCurrentSync } from '@client-platform/api';
import { Collection, Dock3Button, DockCompanionButton } from '@client-platform/shapes';

import { usePlatformIdentity } from '../hooks/usePlatformIdentity';

import { DockComponent } from './DockComponent';
import { CompanionDockButton, DockCompanionSeparator } from './DockStyled';
import EnterpriseDockSelector from './EnterpriseDockSelector';
import { ReorderGroup } from './ReorderGroup';
import { ReorderItem } from './ReorderGroupInner';

// Union type for all possible button types
export type DockButton = DockCompanionButton | Dock3Button;

export interface DefaultDockButtonsPanelProps {
    expandedComponent: DockComponent;
    toggleDockComponent: (component: DockComponent) => void;
    // this flag will go away when we improve manage workspaces button
    // this is necessary to support legacy workspace selector, because dock companion relies on openfin-direct custom implementation through internal platform methods
    platformDockSelector?: boolean;
    dockButtonsManager: {
        defaultDockButtons: DockButton[];
        setDefaultDockButtonsOrder: (updatedDefaultDockButtons: DockButton[]) => void;
    };
    collectionMenu?: Collection[];
}

export const BUTTON_DRAG_END_DEBOUNCE = 150;
export const SEARCH_CLICK_DEBOUNCE = 750;

export const DefaultDockButtonsPanel = ({
    expandedComponent,
    toggleDockComponent,
    dockButtonsManager,
    platformDockSelector,
    collectionMenu
}: DefaultDockButtonsPanelProps) => {
    const { defaultDockButtons, setDefaultDockButtonsOrder } = dockButtonsManager;
    const [dragging, setDragging] = useState(false);
    const platformIdentity = usePlatformIdentity();
    // a hack to prevent strange framer behaviour when dragging favorites.
    const [dragDisabled, setDragDisabled] = useState(true);

    const defaultButtonConfig = {
        store: {
            renderButton: () => (
                <CompanionDockButton
                    data-testid={dock3TestIds.buttonStore}
                    tooltip="Store"
                    onClick={async () => {
                        if (dragging) {
                            return;
                        }
                        if (await isWindowRunning(storefrontOFIdentity)) {
                            await showAndFocus(storefrontOFIdentity);
                        }
                    }}
                    rounded
                >
                    <Icon icon="StorefrontIcon" size="xlarge" />
                </CompanionDockButton>
            )
        },
        switchWorkspace: {
            renderButton: () =>
                platformDockSelector ? (
                    <PlatformDockSelector dragging={dragging} platformIdentity={platformIdentity} />
                ) : (
                    <EnterpriseDockSelector dragging={dragging} platformIdentity={platformIdentity} />
                )
        },
        collectionMenu: {
            renderButton: () => (
                <CollectionMenu
                    collectionMenu={collectionMenu}
                    dragging={dragging}
                    platformIdentity={platformIdentity}
                />
            )
        },
        home: {
            renderButton: () => (
                <CompanionDockButton
                    data-testid={dock3TestIds.buttonHome}
                    tooltip="Search From Home Application"
                    onClick={async () => {
                        if (dragging) return;
                        if (await isWindowRunning(homeOFIdentity)) {
                            await showAndFocus(homeOFIdentity);
                        }
                        raiseDockAnalytics(platformIdentity, {
                            type: 'Workspace Section',
                            action: 'Select Dock Item',
                            value: 'home'
                        });
                    }}
                    rounded
                >
                    <Icon icon="MagnifyingGlassIcon" size="xlarge" />
                </CompanionDockButton>
            )
        },
        searchShortcut: {
            renderButton: () => (
                <CompanionDockButton
                    data-testid={dock3TestIds.buttonSearch}
                    tooltip="Search"
                    onClick={debounce(
                        () => {
                            if (dragging) {
                                return;
                            }

                            // eslint-disable-next-line no-underscore-dangle
                            getCurrentSync()._focusAndExpandSearchInternal();
                        },
                        SEARCH_CLICK_DEBOUNCE,
                        { leading: true, trailing: false }
                    )}
                    rounded
                >
                    <Icon icon="MagnifyingGlassIcon" size="xlarge" />
                </CompanionDockButton>
            )
        },
        notifications: {
            renderButton: () => <NotificationsButton oversized={true} dragging={dragging} />
        },
        contentMenu: {
            renderButton: () => (
                <CompanionDockButton
                    data-testid={dock3TestIds.buttonContentMenu}
                    tooltip="Content Menu"
                    active={expandedComponent === DockComponent.ContentMenu}
                    onClick={() => !dragging && toggleDockComponent(DockComponent.ContentMenu)}
                    rounded
                >
                    <ContentMenuIcon />
                </CompanionDockButton>
            )
        },
        bookmarks: {
            renderButton: () => (
                <CompanionDockButton
                    data-testid={dock3TestIds.buttonBookmarks}
                    tooltip="Bookmarks"
                    active={expandedComponent === DockComponent.Bookmarks}
                    onClick={() => !dragging && toggleDockComponent(DockComponent.Bookmarks)}
                    rounded
                >
                    <DockBookmark />
                </CompanionDockButton>
            )
        },
        manageWorkspaces: {
            renderButton: () => <ManageWorkspaces platformIdentity={platformIdentity} dragging={dragging} />
        }
    };

    const handleReorderEnd = (e: DockButton[]) => {
        raiseDockAnalytics(platformIdentity, {
            type: 'Workspace Section',
            action: 'Move Workspace Component',
            value: e.join(', '),
            skipValueHashing: true
        });
        setDefaultDockButtonsOrder(e);
    };

    const renderButton = (btn: DockButton) => {
        const config = defaultButtonConfig[btn as keyof typeof defaultButtonConfig];
        if (!config) {
            console.warn(`No button config found for: ${btn}`);
            return null;
        }
        return config.renderButton();
    };

    return (
        <>
            <DockCompanionSeparator />
            <List data-testid={dock3TestIds.defaultButtonsList} onMouseEnter={() => setDragDisabled(false)}>
                <DefaultDockButtonsReorderGroup items={defaultDockButtons} onReorderEnd={handleReorderEnd}>
                    {(buttons) =>
                        buttons.map((btn) => (
                            <ReorderItem
                                onDragStart={() => setDragging(true)}
                                onDragEnd={debounce(() => setDragging(false), BUTTON_DRAG_END_DEBOUNCE)}
                                key={`dock-button-${btn}`}
                                value={btn}
                                disabled={dragDisabled}
                                data-testid={dock3TestIds.reorderItem(btn)}
                            >
                                {renderButton(btn)}
                            </ReorderItem>
                        ))
                    }
                </DefaultDockButtonsReorderGroup>
            </List>
        </>
    );
};

const List = styled(motion.div)`
    display: flex;
    overflow: hidden;
`;

const DefaultDockButtonsReorderGroup = styled(ReorderGroup<DockButton>)`
    display: flex;
    align-items: center;
    gap: ${({ theme }) => theme.px.small};
`;
