// new file: hooks/useDockExpansion.ts
import { useCallback, useState } from 'react';

import type { OpenFin } from '@openfin/core';

import { DOCK_COMPANION_HEIGHT } from '@dock3/api/constants';

import { DockComponent } from '@dock3/components/DockComponent';
import { getDockComponentHeight } from '@dock3/components/DockLayout';
import { getShouldAnchorDockAtBottom, resizeDockWindow } from '@dock3/components/utils';

export const useDockExpansion = (onClose?: () => void) => {
    const [expandedComponent, setExpandedComponent] = useState<DockComponent>();
    const [isExpandedUp, setIsExpandedUp] = useState<boolean>();

    const toggleDockComponent = useCallback(
        async (dockComponent?: DockComponent) => {
            const dockWindow = fin.me as OpenFin.Window;

            // Toggle to close the currently expanded component
            if (!dockComponent || dockComponent === expandedComponent) {
                setExpandedComponent(null);
                onClose?.(); // Call the optional on-close callback
                resizeDockWindow(dockWindow, DOCK_COMPANION_HEIGHT, isExpandedUp);
                return;
            }

            const newDockHeight = getDockComponentHeight(dockComponent);
            const shouldExpandUp = expandedComponent
                ? isExpandedUp
                : await getShouldAnchorDockAtBottom(dockWindow, newDockHeight);

            setExpandedComponent(dockComponent);
            setIsExpandedUp(shouldExpandUp);
            resizeDockWindow(dockWindow, newDockHeight, shouldExpandUp);
        },
        [expandedComponent, isExpandedUp, onClose]
    );

    return { expandedComponent, isExpandedUp, toggleDockComponent };
};
