import type { OpenFin } from '@openfin/core';

import { useInitialOptions } from '@common/utils/useInitialOptions';

import type { CompanionDockConfig, Dock3Config } from '@client-platform/shapes';

// Union type for dock configuration
export type DockConfiguration = CompanionDockConfig | Dock3Config;

/**
 * Custom hook that retrieves the dock buttons and workspace buttons based on the provided context.
 *
 * @param configType - The type of configuration to retrieve (CompanionDockConfig | Dock3Config).
 * @returns An object containing the workspace buttons and dock buttons that are displayed in the PanelContainer component.
 */
export const useCompanionDockConfiguration = <T extends DockConfiguration = DockConfiguration>(): T | null => {
    return useInitialOptions<OpenFin.WindowOptions>()?.workspacePlatform as T;
};
