import React, { useContext } from 'react';

import { DefaultDockButtonsPanel } from '@dock3/components/DefaultDockButtons';
import { DockComponent } from '@dock3/components/DockComponent';

import { Collection, CompanionDockConfig } from '@client-platform/shapes';
import { useCompanionDockConfiguration } from '@dock3/hooks/useCompanionDockConfiguration';
import { useDefaultDockButtonsDynamic } from '@dock3/hooks/useDefaultDockButtonsDynamic';
import { DockContext } from '@enterprise/context/DockContext';

export interface DefaultDockButtonsPanelProps {
    expandedComponent: DockComponent;
    toggleDockComponent: (component: DockComponent) => void;
    collectionMenu?: Collection[];
}

export const EnterpriseDefaultDockButtonsPanel = ({
    expandedComponent,
    toggleDockComponent
}: DefaultDockButtonsPanelProps) => {
    const config = useCompanionDockConfiguration<CompanionDockConfig>();
    const { collectionMenu } = useContext(DockContext);
    const [defaultDockButtons, setDefaultDockButtonsOrder] = useDefaultDockButtonsDynamic(config);

    if (!defaultDockButtons.length) {
        return null;
    }

    return (
        <DefaultDockButtonsPanel
            expandedComponent={expandedComponent}
            toggleDockComponent={toggleDockComponent}
            dockButtonsManager={{
                defaultDockButtons,
                setDefaultDockButtonsOrder
            }}
            collectionMenu={collectionMenu}
        />
    );
};
